// testdata/ts_auth_vectors.json is generated by running the compiled
// TypeScript sources (src/auth/session.ts, device-token.ts, proxy-ticket.ts,
// proxy-next.ts) under Node with Date.now and crypto.randomBytes pinned.

type tsAuthVectors struct {
	Sessions []struct {
		Name  string `json:"name"`
		NowMS int64  `json:"nowMs"`
		User  struct {
			UnionID string            `json:"unionId"`
			OpenID  string            `json:"openId"`
			Name    string            `json:"name"`
			Avatar  string            `json:"avatar"`
			UT      *SessionUserToken `json:"ut"`
			SS      bool              `json:"ss"`
		} `json:"user"`
		Token string `json:"token"`
	} `json:"sessions"`
	Renew []struct {
		Name  string           `json:"name"`
		Input string           `json:"input"`
		NowMS int64            `json:"nowMs"`
		UT    SessionUserToken `json:"ut"`
		Want  string           `json:"want"`
	} `json:"renew"`
	DeviceAccess []struct {
		Name string `json:"name"`
		Doc  struct {
			ID                string   `json:"_id"`
			UnionID           string   `json:"unionId"`
			CredentialVersion int64    `json:"credentialVersion"`
			Scopes            []string `json:"scopes"`
			DeviceExp         int64    `json:"deviceExp"`
		} `json:"doc"`
		NowMS int64  `json:"nowMs"`
		Token string `json:"token"`
	} `json:"deviceAccess"`
	SHA256 []struct {
		In  string `json:"in"`
		Out string `json:"out"`
	} `json:"sha256"`
	JTI []struct {
		PrevHash string `json:"prevHash"`
		Key      string `json:"key"`
		Gen      int64  `json:"gen"`
		JTI      string `json:"jti"`
	} `json:"jti"`
	Refresh []struct {
		Claims struct {
			DeviceID          string `json:"deviceId"`
			FamilyID          string `json:"familyId"`
			Generation        int64  `json:"generation"`
			JTI               string `json:"jti"`
			CredentialVersion int64  `json:"credentialVersion"`
			DeviceExpMS       int64  `json:"deviceExpMs"`
		} `json:"claims"`
		Token string `json:"token"`
	} `json:"refresh"`
	ProxyTicket struct {
		NowMS int64  `json:"nowMs"`
		JTI   string `json:"jti"`
		Token string `json:"token"`
	} `json:"proxyTicket"`
	ProxySession struct {
		NowMS int64  `json:"nowMs"`
		Token string `json:"token"`
	} `json:"proxySession"`
	DeviceProxy struct {
		NowMS             int64             `json:"nowMs"`
		Claims            DeviceProxyClaims `json:"claims"`
		TicketJTI         string            `json:"ticketJti"`
		Ticket            string            `json:"ticket"`
		SessionFromClaims string            `json:"sessionFromClaims"`
		SessionFromTicket string            `json:"sessionFromTicket"`
		SessionRenewed    string            `json:"sessionRenewed"`
		ShortClaims       DeviceProxyClaims `json:"shortClaims"`
		ShortTicketJTI    string            `json:"shortTicketJti"`
		ShortTicket       string            `json:"shortTicket"`
	} `json:"deviceProxy"`
	Cookies map[string]struct {
		ClearProxy          string   `json:"clearProxy"`
		ProxyHeaders        []string `json:"proxyHeaders"`
		ClearDashboard      string   `json:"clearDashboard"`
		ClearTerminal       string   `json:"clearTerminal"`
		SetDashboard        string   `json:"setDashboard"`
		SetTerminalNegative string   `json:"setTerminalNegative"`
	} `json:"cookies"`
	Presence []struct {
		Cookie  string             `json:"cookie"`
		Purpose DeviceProxyPurpose `json:"purpose"`
		Has     bool               `json:"has"`
	} `json:"presence"`
	Next []struct {
		In  string  `json:"in"`
		Out *string `json:"out"`
	} `json:"next"`
}

func loadTSAuthVectors(t *testing.T) tsAuthVectors {
	t.Helper()
	raw, err := os.ReadFile("testdata/ts_auth_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v tsAuthVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func vectorConfig() config.Config {
	return config.Config{SigningSecret: "compat-secret-123", SessionTTL: time.Hour}
}

func TestSessionMatchesTypeScriptVectors(t *testing.T) {
	t.Parallel()
	v := loadTSAuthVectors(t)
	cfg := vectorConfig()
	for _, tc := range v.Sessions {
		got := MintSessionAt(cfg, SessionUser{
			UnionID: tc.User.UnionID, OpenID: tc.User.OpenID, Name: tc.User.Name, Avatar: tc.User.Avatar,
			UserToken: tc.User.UT, SearchScope: tc.User.SS,
		}, time.UnixMilli(tc.NowMS))
		if got != tc.Token {
			t.Errorf("mint %q\n got %s\nwant %s", tc.Name, got, tc.Token)
		}
	}
	for _, tc := range v.Renew {
		session, err := VerifySessionAt(cfg, tc.Input, time.Unix(1700000000, 0))
		if err != nil {
			t.Fatalf("%s: verify input: %v", tc.Name, err)
		}
		if got := RenewSessionUserTokenAt(cfg, session, tc.UT, time.UnixMilli(tc.NowMS)); got != tc.Want {
			t.Errorf("renew %q\n got %s\nwant %s", tc.Name, got, tc.Want)
		}
	}
}

func TestRenewSessionKeepsAuthTimeAndLegacyStaleness(t *testing.T) {
	t.Parallel()
	cfg := vectorConfig()
	now := time.Unix(1700000000, 0)
	fresh, _ := VerifySessionAt(cfg, MintSessionAt(cfg, SessionUser{UnionID: "u", Name: "U", SearchScope: true}, now.Add(-time.Hour)), now)
	renewed, err := VerifySessionAt(cfg, RenewSessionUserTokenAt(cfg, fresh, SessionUserToken{AccessToken: "a"}, now), now)
	if err != nil || renewed.AuthTime == nil || *renewed.AuthTime != now.Add(-time.Hour).Unix() || !renewed.SearchScope || renewed.Exp != now.Unix()+3600 {
		t.Fatalf("renewed = %+v err = %v", renewed, err)
	}
	// A Go-built payload without authTime stays without it.
	legacy := &SessionPayload{Kind: "session", UnionID: "old", Name: "Old", Exp: now.Unix() + 60}
	renewedLegacy, err := VerifySessionAt(cfg, RenewSessionUserTokenAt(cfg, legacy, SessionUserToken{AccessToken: "a"}, now), now)
	if err != nil || renewedLegacy.AuthTime != nil || renewedLegacy.UserToken == nil || renewedLegacy.UserToken.AccessToken != "a" {
		t.Fatalf("renewed legacy = %+v err = %v", renewedLegacy, err)
	}
}

func TestDeviceTokensMatchTypeScriptVectors(t *testing.T) {
	t.Parallel()
	v := loadTSAuthVectors(t)
	cfg := vectorConfig()
	for _, tc := range v.DeviceAccess {
		doc := store.DeviceDoc{ID: tc.Doc.ID, UnionID: tc.Doc.UnionID, CredentialVersion: tc.Doc.CredentialVersion, Scopes: tc.Doc.Scopes, DeviceExp: tc.Doc.DeviceExp}
		if got := MintDeviceAccessToken(cfg, doc, tc.NowMS); got != tc.Token {
			t.Errorf("access %q\n got %s\nwant %s", tc.Name, got, tc.Token)
		}
	}
	for _, tc := range v.SHA256 {
		if got := SHA256Hex(tc.In); got != tc.Out {
			t.Errorf("sha256(%q) = %s, want %s", tc.In, got, tc.Out)
		}
	}
	for _, tc := range v.JTI {
		if got := DeriveRefreshJTI(cfg, tc.PrevHash, tc.Key, tc.Gen); got != tc.JTI {
			t.Errorf("jti(%q,%q,%d) = %s, want %s", tc.PrevHash, tc.Key, tc.Gen, got, tc.JTI)
		}
	}
	for _, tc := range v.Refresh {
		c := tc.Claims
		got := BuildDeviceRefreshToken(cfg, DeviceRefreshClaims{DeviceID: c.DeviceID, FamilyID: c.FamilyID, Generation: c.Generation, JTI: c.JTI, CredentialVersion: c.CredentialVersion, DeviceExpMS: c.DeviceExpMS})
		if got != tc.Token {
			t.Errorf("refresh %+v\n got %s\nwant %s", c, got, tc.Token)
		}
	}
}

func TestProxyTicketsMatchTypeScriptVectors(t *testing.T) {
	t.Parallel()
	v := loadTSAuthVectors(t)
	cfg := vectorConfig()
	cfg.SessionTTL = time.Hour
	now := time.UnixMilli(v.ProxyTicket.NowMS)
	if got := issueProxyTicket(cfg, ProxyIdentity{UnionID: "on_abc", MachineID: "deadbeefcafebabe"}, now, v.ProxyTicket.JTI); got != v.ProxyTicket.Token {
		t.Errorf("proxy ticket\n got %s\nwant %s", got, v.ProxyTicket.Token)
	}
	if ticket, err := VerifyProxyTicketAt(cfg, v.ProxyTicket.Token, now); err != nil || ticket.JTI != v.ProxyTicket.JTI {
		t.Errorf("verify proxy ticket = %+v, %v", ticket, err)
	}
	if got := MintProxySessionAt(cfg, ProxyIdentity{UnionID: "on_abc", MachineID: "deadbeefcafebabe"}, now); got != v.ProxySession.Token {
		t.Errorf("proxy session\n got %s\nwant %s", got, v.ProxySession.Token)
	}

	d := v.DeviceProxy
	now = time.UnixMilli(d.NowMS)
	if got := issueDeviceProxyTicket(cfg, d.Claims, now, d.TicketJTI); got != d.Ticket {
		t.Errorf("device ticket\n got %s\nwant %s", got, d.Ticket)
	}
	if got := issueDeviceProxyTicket(cfg, d.ShortClaims, now, d.ShortTicketJTI); got != d.ShortTicket {
		t.Errorf("short device ticket\n got %s\nwant %s", got, d.ShortTicket)
	}
	if got := MintDeviceProxySession(cfg, d.Claims); got != d.SessionFromClaims {
		t.Errorf("device session from claims\n got %s\nwant %s", got, d.SessionFromClaims)
	}
	ticket, err := VerifyDeviceProxyTicketAt(cfg, d.Ticket, now)
	if err != nil || !reflect.DeepEqual(ticket.DeviceProxyClaims, d.Claims) || ticket.JTI != d.TicketJTI {
		t.Fatalf("verify device ticket = %+v, %v", ticket, err)
	}
	if got := MintDeviceProxySessionFromTicket(cfg, ticket); got != d.SessionFromTicket {
		t.Errorf("device session from ticket\n got %s\nwant %s", got, d.SessionFromTicket)
	}
	session, err := VerifyDeviceProxySessionTokenAt(cfg, d.SessionFromTicket, now)
	if err != nil || session.JTI != d.TicketJTI {
		t.Fatalf("verify device session = %+v, %v", session, err)
	}
	if got := RenewDeviceProxySession(cfg, session); got != d.SessionRenewed {
		t.Errorf("renewed device session\n got %s\nwant %s", got, d.SessionRenewed)
	}
	// Kinds never cross: a session is not a ticket and vice versa.
	if _, err := VerifyDeviceProxyTicketAt(cfg, d.SessionFromTicket, now); err == nil {
		t.Error("device session accepted as ticket")
	}
	if _, err := VerifyDeviceProxySessionTokenAt(cfg, d.Ticket, now); err == nil {
		t.Error("device ticket accepted as session")
	}
	if _, err := VerifyProxyTicketAt(cfg, d.Ticket, now); err == nil {
		t.Error("device ticket accepted as owner proxy ticket")
	}
}

func TestProxyCookieHeadersMatchTypeScriptVectors(t *testing.T) {
	t.Parallel()
	v := loadTSAuthVectors(t)
	for label, want := range v.Cookies {
		cfg := vectorConfig()
		cfg.CookieSecure = label == "secure"
		check := func(name, got, want string) {
			if got != want {
				t.Errorf("%s %s\n got %q\nwant %q", label, name, got, want)
			}
		}
		check("clearProxy", ClearProxySessionCookieHeader(cfg), want.ClearProxy)
		if got := ProxySessionCookieHeaders(cfg, "TOKEN"); !reflect.DeepEqual(got, want.ProxyHeaders) {
			t.Errorf("%s proxyHeaders\n got %q\nwant %q", label, got, want.ProxyHeaders)
		}
		check("clearDashboard", ClearDeviceProxySessionCookieHeader(cfg, DeviceProxyPurposeDashboardMobile), want.ClearDashboard)
		check("clearTerminal", ClearDeviceProxySessionCookieHeader(cfg, DeviceProxyPurposeTerminal), want.ClearTerminal)
		check("setDashboard", DeviceProxySessionCookieHeader(cfg, "TOK", 120, DeviceProxyPurposeDashboardMobile), want.SetDashboard)
		check("setTerminalNegative", DeviceProxySessionCookieHeader(cfg, "TOK", -5, DeviceProxyPurposeTerminal), want.SetTerminalNegative)
	}
	for _, tc := range v.Presence {
		req := httptest.NewRequest("GET", "http://m-x.example/", nil)
		if tc.Cookie != "" {
			req.Header.Set("Cookie", tc.Cookie)
		}
		if got := HasDeviceProxySessionCookie(req, tc.Purpose); got != tc.Has {
			t.Errorf("presence(%q, %s) = %v, want %v", tc.Cookie, tc.Purpose, got, tc.Has)
		}
	}
}

func TestSafeProxyNextPathMatchesTypeScriptVectors(t *testing.T) {
	t.Parallel()
	v := loadTSAuthVectors(t)
	for _, tc := range v.Next {
		got, ok := SafeProxyNextPath(tc.In)
		if (tc.Out == nil) != !ok || (ok && got != *tc.Out) {
			t.Errorf("SafeProxyNextPath(%q) = %q,%v want %v", tc.In, got, ok, tc.Out)
		}
	}
	if _, ok := SafeProxyNextPath("/\xff"); ok {
		t.Error("invalid UTF-8 accepted")
	}
}
